public static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == suffix;
    }
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == suffix;
    }
    int len = suffix.length();
    int diff = str.length() - len;
    if (diff < 0) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, diff, suffix, 0, len);
    } else {
        return str.regionMatches(false, diff, suffix, 0, len);
    }
}

